style.css:
/* Apply the custom cursor to the entire website */
html, body {
    cursor: url('https://squarespace-cdn.com') 16 16, auto;
}

/* Optional: Ensure the cursor changes properly when hovering over clickable links and buttons */
a, button, input[type="submit"], select {
    cursor: url('https://squarespace-cdn.com') 16 16, pointer;
}
